import{_ as a,o as t,c as i,an as r}from"./chunks/framework.D7m_-RyX.js";const u=JSON.parse('{"title":"API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/index.md","filePath":"reference/index.md","lastUpdated":null}'),o={name:"reference/index.md"};function n(s,e,l,p,d,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="API-Reference" tabindex="-1">API Reference <a class="header-anchor" href="#API-Reference" aria-label="Permalink to &quot;API Reference {#API-Reference}&quot;">​</a></h1><p>Every exported type and function is documented here, grouped by what it is for. If you are after a worked example rather than a signature, the <a href="./../tutorials/">tutorials</a> are the better place to start.</p><p>Most workflows only touch the first four groups. Solvers, preconditioners and linear maps matter when you are tuning performance or extending the package, and can be ignored until then.</p><h2 id="Core-types" tabindex="-1">Core types <a class="header-anchor" href="#Core-types" aria-label="Permalink to &quot;Core types {#Core-types}&quot;">​</a></h2><ul><li><p><a href="./gmrfs">GMRFs</a> — the distribution types themselves, and the operations they support: means, marginal variances, sampling, conditioning.</p></li><li><p><a href="./hard_constraints">Hard Constraints</a> — <code>ConstrainedGMRF</code>, for models that must satisfy linear equality constraints exactly.</p></li></ul><h2 id="Building-models" tabindex="-1">Building models <a class="header-anchor" href="#Building-models" aria-label="Permalink to &quot;Building models {#Building-models}&quot;">​</a></h2><ul><li><p><a href="./latent_models">Latent Models</a> — the <code>LatentModel</code> interface and the models that ship with the package: AR, RW, IID, Besag, BYM2, Matérn, and their combinations.</p></li><li><p><a href="./autoregressive">Autoregressive Models</a> — autoregressive and conditional autoregressive constructors.</p></li><li><p><a href="./formula">Formula Interface</a> — composing models with <code>StatsModels.jl</code> formula syntax, which assembles the latent components and design matrix for you.</p></li><li><p><a href="./spatial_utils">Spatial Utilities</a> — building adjacency structures, such as contiguity matrices from polygons.</p></li></ul><h2 id="SPDE-discretizations" tabindex="-1">SPDE discretizations <a class="header-anchor" href="#SPDE-discretizations" aria-label="Permalink to &quot;SPDE discretizations {#SPDE-discretizations}&quot;">​</a></h2><ul><li><p><a href="./spdes">SPDEs</a> — the <code>SPDE</code> type and the equations that ship with the package.</p></li><li><p><a href="./discretizations">Discretizations</a> — turning an SPDE into a GMRF, in space and in space-time.</p></li><li><p><a href="./meshes">Meshes</a> — helpers for constructing the finite element meshes those discretizations need.</p></li></ul><h2 id="Observations-and-inference" tabindex="-1">Observations and inference <a class="header-anchor" href="#Observations-and-inference" aria-label="Permalink to &quot;Observations and inference {#Observations-and-inference}&quot;">​</a></h2><ul><li><p><a href="./observation_models">Observation Models</a> — how data relates to the latent field, from exponential families to custom autodiff-defined likelihoods.</p></li><li><p><a href="./gaussian_approximation">Gaussian Approximation</a> — Laplace approximation of the posterior for non-Gaussian likelihoods.</p></li><li><p><a href="./autodiff">Automatic Differentiation</a> — supported backends, what is differentiable, and the current limitations.</p></li></ul><h2 id="Computation-and-performance" tabindex="-1">Computation and performance <a class="header-anchor" href="#Computation-and-performance" aria-label="Permalink to &quot;Computation and performance {#Computation-and-performance}&quot;">​</a></h2><ul><li><p><a href="./solvers">Solvers</a> — the sparse linear algebra backends that everything else is built on.</p></li><li><p><a href="./preconditioners">Preconditioners</a> — preconditioning for iterative solvers.</p></li><li><p><a href="./workspaces">Workspaces</a> — reusing a symbolic factorization across many precision matrices with the same sparsity pattern.</p></li><li><p><a href="./linear_maps">Linear maps</a> — the structured matrix types used to keep precision matrices cheap.</p></li></ul><h2 id="Further-topics" tabindex="-1">Further topics <a class="header-anchor" href="#Further-topics" aria-label="Permalink to &quot;Further topics {#Further-topics}&quot;">​</a></h2><ul><li><p><a href="./kl_approximation">KL Approximations</a> — approximating a kernel-defined Gaussian process by a sparse GMRF, without going via an SPDE.</p></li><li><p><a href="./graphical_lasso">Graphical Lasso</a> — estimating a sparse precision matrix from data when the structure is unknown.</p></li><li><p><a href="./plotting">Plotting</a> — Makie recipes for spatial and spatiotemporal GMRFs.</p></li></ul>',15)])])}const f=a(o,[["render",n]]);export{u as __pageData,f as default};
